const MULTI_VALUE_FILTER_VARIANTS: FilterVariant[] = [
    'select',
    'multi-select',
    'range',
    'date-range',
];

const FILTER_OPERATORS_BY_VARIANT: Record<
    FilterVariant,
    FilterOperatorOption[]
> = {
    text: TEXT_OPERATORS,
    number: NUMERIC_OPERATORS,
    range: NUMERIC_OPERATORS,
    date: DATE_OPERATORS,
    'date-range': DATE_OPERATORS,
    boolean: BOOLEAN_OPERATORS,
    select: SELECT_OPERATORS,
    'multi-select': MULTI_SELECT_OPERATORS,
};

export function getAriaSort(
    sorting: SortingState,
    columnId: string,
): React.AriaAttributes['aria-sort'] {
    const sort = sorting[0];
    if (sort?.id !== columnId) return undefined;
    return sort.desc ? 'descending' : 'ascending';
}

export function getVisibleSelectedRows<TData extends RowData>(
    table: Table<DataTableFeatures, TData>,
) {
    return table.getRowModel().rows.filter((row) => row.getIsSelected());
}

export function getColumnPinningStyle<TData extends RowData>(
    column: Column<DataTableFeatures, TData>,
    isPinned = column.getIsPinned(),
): React.CSSProperties {
    return {
        insetInlineStart:
            isPinned === 'start'
                ? `var(${getColumnVar(column.id, 'offset')})`
                : undefined,
        insetInlineEnd:
            isPinned === 'end'
                ? `var(${getColumnVar(column.id, 'offset')})`
                : undefined,
        position: isPinned ? 'sticky' : 'relative',
        // The width is the `w-(--cell-size)` class of the cell, so the Tailwind
        // classes of `meta.className` can replace it (an inline width cannot).
        ['--cell-size' as string]: `var(${getColumnVar(column.id, 'size')})`,
        zIndex: isPinned ? 20 : undefined,
    };
}

/**
 * Width class and the `meta` classes of a column, for its header or its cells
 * (to combine with `cn`, which lets a `w-*` of the page replace the default).
 */
export function getColumnClassName(
    meta: DataTableColumnMeta | undefined,
    part: 'header' | 'cell',
    cell?: Cell<DataTableFeatures, RowData>,
): string[] {
    const own =
        part === 'header'
            ? meta?.headerClassName
            : typeof meta?.cellClassName === 'function'
              ? cell
                  ? meta.cellClassName(cell)
                  : undefined
              : meta?.cellClassName;

    return [
        'w-(--cell-size)',
        ALIGN_CLASSES[getColumnAlign(meta)],
        meta?.className,
        own,
    ].filter((item): item is string => typeof item === 'string' && item !== '');
}

export function getColumnSizingStyle<TData extends RowData>(
    table: Table<DataTableFeatures, TData>,
): React.CSSProperties {
    // No minWidth: with `table-fixed` the browser already widens the table to
    // the sum of its columns, also when Tailwind classes change their width.
    const style: Record<string, string> = {};

    for (const header of table.getFlatHeaders()) {
        style[getColumnVar(header.column.id, 'size')] = `${header.getSize()}px`;
    }

    for (const { column } of table.getLeafHeaders()) {
        const isPinned = column.getIsPinned();
        if (!isPinned) continue;

        const offset =
            isPinned === 'start'
                ? column.getStart('start')
                : column.getAfter('end');
        style[getColumnVar(column.id, 'offset')] = `${offset}px`;
    }

    return style;
}

export function getFilterOperators(filterVariant: FilterVariant) {
    return FILTER_OPERATORS_BY_VARIANT[filterVariant] ?? [];
}

export function getDefaultFilterOperator(filterVariant: FilterVariant) {
    const operators = getFilterOperators(filterVariant);

    return operators[0]?.value ?? (filterVariant === 'text' ? 'iLike' : 'eq');
}

export function getIsEditableTarget(target: EventTarget | null) {
    if (!(target instanceof HTMLElement)) return false;

    return (
        target.isContentEditable ||
        target instanceof HTMLInputElement ||
        target instanceof HTMLTextAreaElement ||
        target instanceof HTMLSelectElement
    );
}

export function getIsValuelessOperator(operator: FilterOperator) {
    return operator === 'isEmpty' || operator === 'isNotEmpty';
}

export function coerceFilterValue(
    operator: FilterOperator,
    value: string | string[],
) {
    if (getIsValuelessOperator(operator)) return '';

    if (operator === 'inArray' || operator === 'notInArray') {
        if (Array.isArray(value)) return value;
        return value ? [value] : [];
    }

    if (operator === 'isBetween') {
        return Array.isArray(value) ? value : [value, ''];
    }

    if (Array.isArray(value)) return value.find((item) => item !== '') ?? '';

    return value;
}

export function getFilterVariant(
    meta: ColumnVariantMeta | undefined,
): FilterVariant {
    switch (meta?.variant) {
        case 'number':
            return meta.filter === 'range' ? 'range' : 'number';
        case 'date':
            return meta.filter === 'range' ? 'date-range' : 'date';
        case 'boolean':
        case 'select':
        case 'multi-select':
            return meta.variant;
        default:
            return 'text';
    }
}

export function getColumnSelectOptions(
    meta: ColumnVariantMeta | undefined,
): ColumnSelectOption[] {
    return meta?.variant === 'select' || meta?.variant === 'multi-select'
        ? (meta.options ?? [])
        : [];
}

export function getDefaultFilter<TData extends RowData>(
    column: Column<DataTableFeatures, TData>,
) {
    const variant = getFilterVariant(column.columnDef.meta);

    return {
        id: column.id,
        variant,
        operator: getDefaultFilterOperator(variant),
        value: '',
    };
}

export function getSelectFilterValue(filter: ColumnFilterItem) {
    if (filter.variant === 'multi-select') {
        return Array.isArray(filter.value) ? filter.value : [];
    }

    return typeof filter.value === 'string' ? filter.value : undefined;
}

/**
 * Whether the default cell of the column is a number cell.
 */
export function isNumberColumn(meta: DataTableColumnMeta | undefined) {
    return meta?.display
        ? meta.display.type === 'number'
        : meta?.variant === 'number';
}

/**
 * Alignment of the header and the cells of a column: `meta.align`, else `end`
 * for numbers (figures line up) and `start` for the rest.
 */
export function getColumnAlign(
    meta: DataTableColumnMeta | undefined,
): DataTableAlign {
    return meta?.align ?? (isNumberColumn(meta) ? 'end' : 'start');
}

// `end` adds room before the next column, which usually starts at its start.
const ALIGN_CLASSES: Record<DataTableAlign, string> = {
    start: 'text-start',
    center: 'text-center',
    end: 'pe-8 text-end',
};

function getColumnVar(columnId: string, property: 'size' | 'offset') {
    const name = columnId.replace(
        /[^a-zA-Z0-9-]/g,
        (char) => `_${char.codePointAt(0)?.toString(16)}_`,
    );
    return `--column-${name}-${property}`;
}

const CALENDAR_DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

export function parseFilterDate(value: unknown): Date | undefined {
    if (value instanceof Date) return getValidDate(value);
    if (typeof value === 'number') return getValidDate(new Date(value));
    if (typeof value !== 'string' || value.trim() === '') return undefined;

    const text = value.trim();
    const match = CALENDAR_DATE_PATTERN.exec(text);
    if (match) {
        const [, year, month, day] = match.map(Number);
        if (year === undefined || month === undefined || day === undefined) {
            return undefined;
        }
        const date = new Date(year, month - 1, day);
        return date.getFullYear() === year &&
            date.getMonth() === month - 1 &&
            date.getDate() === day
            ? date
            : undefined;
    }

    const numeric = Number(text);
    return getValidDate(new Date(Number.isNaN(numeric) ? text : numeric));
}

export function formatFilterDate(date: Date) {
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${date.getFullYear()}-${month}-${day}`;
}

export function getIsDateVariant(variant: FilterVariant) {
    return variant === 'date' || variant === 'date-range';
}

export function getFilterDates(value: ColumnFilterItem['value']) {
    return (Array.isArray(value) ? value : [value]).flatMap((item) => {
        const date = parseFilterDate(item);
        return date ? [date] : [];
    });
}

export function getFilterDateValue(date: Date | undefined) {
    return date ? formatFilterDate(date) : '';
}

export function getDateFilterLabel(filter: ColumnFilterItem) {
    const [startDate, endDate] = getFilterDates(filter.value);
    if (!startDate) return undefined;

    const start = formatDate(startDate, { month: 'short' });
    if (
        filter.operator !== 'isBetween' ||
        !endDate ||
        startDate.toDateString() === endDate.toDateString()
    ) {
        return start;
    }

    return `${start} - ${formatDate(endDate, { month: 'short' })}`;
}

export function stringifyFilterValue(value: unknown): string {
    if (value == null) return '';
    if (value instanceof Date) return value.toISOString();
    if (typeof value === 'object') return JSON.stringify(value);
    // oxlint-disable-next-line typescript/no-unnecessary-type-assertion -- narrows `unknown` for no-base-to-string
    return String(value as string | number | boolean | bigint);
}

const UNBOUNDED_RANGE: [number, number] = [-Infinity, Infinity];

export function getRangeFilterBounds(
    values: [string, string],
    [min, max]: [number, number] = UNBOUNDED_RANGE,
): [number | undefined, number | undefined] {
    const [start, end] = values.map((value) => {
        const number = Number(value);
        return value.trim() === '' || Number.isNaN(number)
            ? undefined
            : Math.min(Math.max(number, min), max);
    });

    return start !== undefined && end !== undefined && start > end
        ? [end, start]
        : [start, end];
}

export function getValidRangeFilterBounds(
    values: [string, string],
    [min, max]: [number, number] = UNBOUNDED_RANGE,
): [number | undefined, number | undefined] | null {
    const [start, end] = values.map((value) =>
        value.trim() === '' ? undefined : Number(value),
    );

    for (const bound of [start, end]) {
        if (bound === undefined) continue;
        if (Number.isNaN(bound) || bound < min || bound > max) return null;
    }
    if (start !== undefined && end !== undefined && start > end) return null;

    return [start, end];
}

export function getIsMultiValueVariant(variant: FilterVariant) {
    return MULTI_VALUE_FILTER_VARIANTS.includes(variant);
}

export function getPlainFilterOperator(variant: FilterVariant): FilterOperator {
    if (variant === 'select' || variant === 'multi-select') return 'inArray';
    if (variant === 'range' || variant === 'date-range') return 'isBetween';
    return getDefaultFilterOperator(variant);
}

export function getIsPlainFilter(filter: ColumnFilterItem) {
    return (
        filter.operator === getPlainFilterOperator(filter.variant) &&
        Array.isArray(filter.value) === getIsMultiValueVariant(filter.variant)
    );
}

export function getPlainFilterId(columnId: string) {
    return `${columnId}-filter`;
}

export function createPlainFilter<TColumnId extends string>(
    id: TColumnId,
    variant: FilterVariant,
    value: unknown,
): ColumnFilterItem<TColumnId> | null {
    if (value === undefined || value === null || value === '') return null;

    const operator = getPlainFilterOperator(variant);
    const filterId = getPlainFilterId(id);
    const stringify = getFilterValueStringifier(variant, operator);

    if (getIsMultiValueVariant(variant)) {
        const values = normalizeFilterValues(
            variant,
            operator,
            (Array.isArray(value) ? value : [value]).map(stringify),
        );
        if (values.every((item) => item === '')) return null;
        return { id, variant, operator, value: values, filterId };
    }

    if (Array.isArray(value)) return null;

    return { id, variant, operator, value: stringify(value), filterId };
}

export function normalizeColumnFilter(
    filter: ColumnFilter,
    variant: FilterVariant,
): ColumnFilterItem {
    const filterId = filter.filterId ?? getPlainFilterId(filter.id);

    if (filter.operator) {
        const filterVariant = filter.variant ?? variant;
        const stringify = getFilterValueStringifier(
            filterVariant,
            filter.operator,
        );

        return {
            id: filter.id,
            variant: filterVariant,
            operator: filter.operator,
            value: Array.isArray(filter.value)
                ? normalizeFilterValues(
                      filterVariant,
                      filter.operator,
                      filter.value.map(stringify),
                  )
                : stringify(filter.value),
            filterId,
        };
    }

    const item = createPlainFilter(filter.id, variant, filter.value);
    if (item) return { ...item, filterId };

    return {
        id: filter.id,
        variant,
        operator: getPlainFilterOperator(variant),
        value: getIsMultiValueVariant(variant) ? [] : '',
        filterId,
    };
}

export function getPlainFilterValue(filter: ColumnFilterItem): unknown {
    const { variant, value } = filter;

    if (variant === 'select' || variant === 'multi-select') {
        return Array.isArray(value) ? value : [value];
    }

    if (variant === 'range') {
        return Array.isArray(value)
            ? value.map((item) => (item === '' ? undefined : Number(item)))
            : value;
    }

    if (getIsDateVariant(variant)) {
        return Array.isArray(value)
            ? value.map((item) => parseFilterDate(item)?.getTime())
            : parseFilterDate(value)?.getTime();
    }

    return value;
}

export function getIsActiveFilter(filter: ColumnFilterItem) {
    return (
        getIsValuelessOperator(filter.operator) ||
        (Array.isArray(filter.value)
            ? filter.value.some((value) => value !== '')
            : filter.value !== '')
    );
}

export function getActiveFilters<TFilterItem extends ColumnFilterItem>(
    filters: TFilterItem[],
): TFilterItem[] {
    return filters.filter(getIsActiveFilter);
}

function getValidDate(date: Date) {
    return Number.isNaN(date.getTime()) ? undefined : date;
}

function normalizeFilterValues(
    variant: FilterVariant,
    operator: FilterOperator,
    values: string[],
) {
    if (operator !== 'isBetween') return values;

    if (getIsDateVariant(variant)) {
        const [start = '', end = ''] = values;
        const startTime = parseFilterDate(start)?.getTime();
        const endTime = parseFilterDate(end)?.getTime();
        return startTime !== undefined &&
            endTime !== undefined &&
            startTime > endTime
            ? [end, start]
            : [start, end];
    }

    if (variant !== 'number' && variant !== 'range') return values;

    const [start = '', end = ''] = values.map((value) => {
        const trimmed = value.trim();
        return trimmed === '' || Number.isNaN(Number(trimmed)) ? '' : trimmed;
    });

    return start !== '' && end !== '' && Number(start) > Number(end)
        ? [end, start]
        : [start, end];
}

function getFilterValueStringifier(
    variant: FilterVariant,
    operator: FilterOperator,
) {
    return getIsDateVariant(variant) && operator !== 'isRelativeToToday'
        ? stringifyFilterDate
        : stringifyFilterValue;
}

function stringifyFilterDate(value: unknown) {
    const date = parseFilterDate(value);
    return date ? formatFilterDate(date) : '';
}

import { router } from '@inertiajs/react';
import {
    functionalUpdate,
    type ColumnFiltersState,
    type ColumnVisibilityState,
    type PaginationState,
    type RowData,
    type SortingState,
    type TableOptions,
    type Updater,
    useTable,
} from '@tanstack/react-table';
import * as React from 'react';

import {
    DataTableDefaultCell,
    DataTableDefaultHeader,
} from '@/components/data-table/data-table-default-column';
import {
    dataTableFeatures,
    type DataTableFeatures,
} from '@/lib/data-table-features';
import {
    arrangeColumns,
    buildTableUrl,
    type ServerColumnConfig,
    type ServerDataTable,
    type ServerFacetOption,
    type ServerFilter,
    type ServerRangeFacet,
    type ServerTableConfig,
    type ServerTableState,
    stateToQuery,
} from '@/lib/data-table-server';
import {
    type DataTableMessages,
    mergeMessages,
} from '@/lib/data-table-messages';
import type {
    ColumnDisplay,
    ColumnSelectOption,
    DataTableColumnMeta,
} from '@/lib/data-table-types';
import { normalizeColumnFilter } from '@/lib/data-table-utils';

export { getOptionLabel } from '@/components/data-table/data-table-default-column';

type DataTableColumns<TData extends RowData> = TableOptions<
    DataTableFeatures,
    TData
>['columns'];

type DataTableColumn<TData extends RowData> = DataTableColumns<TData>[number];

interface LocalTableState {
    pagination: PaginationState;
    sorting: SortingState;
    columnFilters: ColumnFiltersState;
    globalFilter: string;
    columnVisibility: ColumnVisibilityState;
}

export interface UseServerDataTableOptions<TData extends RowData> {
    /** Inertia prop with the response of the laravel-inertia-datatable package. */
    table: ServerDataTable<TData>;
    /** Name of that prop: visits only reload this prop (`only`). */
    prop: string;
    /**
     * TanStack columns that customize the ones of the table class (same id) or
     * that only exist on the client. The server decides the order, the missing
     * columns and their `meta`.
     */
    columns: DataTableColumns<TData>;
    /** Delay after typing in a filter or the search before requesting the server. */
    debounceMs?: number;
    /**
     * Locale to format numbers and dates, over the one of the server
     * (`inertia-datatable.locale` or the app locale); `'browser'` for the
     * browser's.
     */
    locale?: string;
    /** Texts of the UI to change, over the ones of the server lang files. */
    messages?: Partial<DataTableMessages>;
    getRowId?: TableOptions<DataTableFeatures, TData>['getRowId'];
}

/**
 * TanStack table in server mode: the state lives in the URL and every change
 * is a partial Inertia visit that returns the already processed page.
 */
export function useServerDataTable<TData extends RowData>({
    table: serverTable,
    prop,
    columns,
    debounceMs = 300,
    getRowId = getDefaultRowId,
    locale,
    messages,
}: UseServerDataTableOptions<TData>) {
    const { config, data, facets, meta, state: serverState } = serverTable;

    const [state, setState] = React.useState(() => toLocalState(serverState));
    const [syncedServerState, setSyncedServerState] =
        React.useState(serverState);
    const [draftVersion, setDraftVersion] = React.useState(0);
    const [sentVersion, setSentVersion] = React.useState(0);
    const [isLoading, setIsLoading] = React.useState(false);
    const timeoutRef = React.useRef<ReturnType<typeof setTimeout>>(undefined);
    const chainRef = React.useRef<{
        base: LocalTableState;
        next: LocalTableState;
    } | null>(null);

    // Every response brings the normalized state: it is the source of truth. If
    // the user kept typing after the request, their filters and search are kept
    // so what they are typing is not overwritten.
    if (syncedServerState !== serverState) {
        setSyncedServerState(serverState);
        const fromServer = toLocalState(serverState);
        setState((current) =>
            draftVersion === sentVersion
                ? fromServer
                : {
                      ...fromServer,
                      columnFilters: current.columnFilters,
                      globalFilter: current.globalFilter,
                  },
        );
    }

    React.useEffect(() => () => clearTimeout(timeoutRef.current), []);

    function visit(next: LocalTableState, replace: boolean) {
        const pairs = stateToQuery(toQueryState(next, config), config);

        router.get(
            buildTableUrl(window.location.href, pairs, config.query),
            {},
            {
                only: [prop],
                preserveState: true,
                preserveScroll: true,
                replace,
                onStart: () => setIsLoading(true),
                onFinish: () => setIsLoading(false),
            },
        );
    }

    function visitNow(next: LocalTableState, replace = true) {
        clearTimeout(timeoutRef.current);
        setSentVersion(draftVersion);
        visit(next, replace);
    }

    function visitLater(next: LocalTableState, version: number) {
        clearTimeout(timeoutRef.current);
        timeoutRef.current = setTimeout(() => {
            setSentVersion(version);
            visit(next, true);
        }, debounceMs);
    }

    /**
     * Applies a change on top of the latest state of the same event: several
     * setters in a row (for example, the Reset button) must not overwrite each other.
     */
    function update(
        change: (current: LocalTableState) => LocalTableState,
    ): LocalTableState {
        const pending = chainRef.current;
        const base = pending?.base === state ? pending.next : state;
        const next = change(base);
        chainRef.current = { base: state, next };
        setState(next);

        return next;
    }

    function onPaginationChange(updater: Updater<PaginationState>) {
        const next = update((current) => {
            const pagination = functionalUpdate(updater, current.pagination);

            return {
                ...current,
                pagination:
                    pagination.pageSize === current.pagination.pageSize
                        ? pagination
                        : { ...pagination, pageIndex: 0 },
            };
        });
        visitNow(next, next.pagination.pageSize !== state.pagination.pageSize);
    }

    function onSortingChange(updater: Updater<SortingState>) {
        const next = update((current) => ({
            ...current,
            sorting: functionalUpdate(updater, current.sorting),
            pagination: { ...current.pagination, pageIndex: 0 },
        }));
        visitNow(next);
    }

    function onColumnVisibilityChange(updater: Updater<ColumnVisibilityState>) {
        const next = update((current) => ({
            ...current,
            columnVisibility: functionalUpdate(
                updater,
                current.columnVisibility,
            ),
        }));
        visitNow(next);
    }

    function onColumnFiltersChange(updater: Updater<ColumnFiltersState>) {
        const next = update((current) => ({
            ...current,
            columnFilters: functionalUpdate(updater, current.columnFilters),
            pagination: { ...current.pagination, pageIndex: 0 },
        }));
        const version = draftVersion + 1;
        setDraftVersion(version);
        visitLater(next, version);
    }

    function onGlobalFilterChange(updater: Updater<unknown>) {
        const next = update((current) => {
            const value = functionalUpdate(updater, current.globalFilter);

            return {
                ...current,
                globalFilter: typeof value === 'string' ? value : '',
                pagination: { ...current.pagination, pageIndex: 0 },
            };
        });
        const version = draftVersion + 1;
        setDraftVersion(version);
        visitLater(next, version);
    }

    const tableColumns = React.useMemo(
        () => withServerMeta(columns, config, facets),
        [columns, config, facets],
    );

    const tableMessages = React.useMemo(
        () => mergeMessages(config.messages, messages),
        [config.messages, messages],
    );

    const table = useTable({
        features: dataTableFeatures,
        columns: tableColumns,
        data,
        getRowId,
        meta: {
            pageSizeOptions: config.per_page_options,
            searchable: config.searchable,
            locale: resolveLocale(locale ?? config.locale),
            dateFormat: config.date_format,
            messages: tableMessages,
        },
        rowCount: meta.total,
        // Without rows the server reports 1 page, not 0.
        pageCount: meta.last_page,
        state,
        onPaginationChange,
        onSortingChange,
        onColumnFiltersChange,
        onGlobalFilterChange,
        onColumnVisibilityChange,
        manualPagination: true,
        manualSorting: true,
        manualFiltering: true,
    });

    return { table, isLoading };
}

/** `'browser'` or nothing: the browser locale (Intl without a locale). */
function resolveLocale(locale: string | null | undefined): string | undefined {
    return locale && locale !== 'browser'
        ? locale.replace('_', '-')
        : undefined;
}

function toLocalState(state: ServerTableState): LocalTableState {
    return {
        pagination: state.pagination,
        sorting: state.sorting,
        columnFilters: state.columnFilters,
        globalFilter: state.globalFilter,
        columnVisibility: state.columnVisibility,
    };
}

function toQueryState(state: LocalTableState, config: ServerTableConfig) {
    const variants = new Map(
        config.columns.map((column) => [column.id, column.variant]),
    );
    const filters: ServerFilter[] = [];

    for (const filter of state.columnFilters) {
        const variant = variants.get(filter.id);

        if (!variant) {
            continue;
        }

        const item = normalizeColumnFilter(filter, variant);

        // Dates relative to today: the server does not support them yet.
        if (item.operator === 'isRelativeToToday') {
            continue;
        }

        filters.push({
            id: item.id,
            variant,
            operator: item.operator,
            value: item.value,
        });
    }

    return {
        pageIndex: state.pagination.pageIndex,
        pageSize: state.pagination.pageSize,
        sorting: state.sorting,
        filters,
        globalFilter: state.globalFilter,
        columnVisibility: state.columnVisibility,
    };
}

/**
 * Orders the columns like the table class, creates the ones the component does
 * not declare and fills each one with what the server declares: label, filter
 * variant, options with counts, range bounds and capabilities. The `meta`
 * declared by the page (for example, icons) takes precedence.
 */
function withServerMeta<TData extends RowData>(
    columns: DataTableColumns<TData>,
    config: ServerTableConfig,
    facets: ServerDataTable<TData>['facets'],
): DataTableColumns<TData> {
    return arrangeColumns(
        columns,
        config.columns.map((column) => column.id),
        {
            getId: getColumnId,
            isLeading: (column) =>
                (column.meta as DataTableColumnMeta | undefined)?.position ===
                'start',
            resolve: (id, column) => {
                const server = config.columns.find((item) => item.id === id);

                return server
                    ? withColumnMeta(
                          withDefaults(column ?? defaultColumn<TData>(id)),
                          server,
                          facets[id],
                      )
                    : (column ?? defaultColumn<TData>(id));
            },
        },
    );
}

/**
 * Column of the table class that the component does not declare: reads the
 * value by id, which is how the server builds each row.
 */
function defaultColumn<TData extends RowData>(
    id: string,
): DataTableColumn<TData> {
    return {
        id,
        accessorFn: (row: TData) => (row as Record<string, unknown>)[id],
    } as DataTableColumn<TData>;
}

/**
 * Default header and cell for whatever the component does not customize:
 * declaring `cell` is enough to change only how the value looks.
 */
function withDefaults<TData extends RowData>(
    column: DataTableColumn<TData>,
): DataTableColumn<TData> {
    return {
        ...column,
        header: column.header ?? DataTableDefaultHeader,
        cell: column.cell ?? DataTableDefaultCell,
    } as DataTableColumn<TData>;
}

function withColumnMeta<TData extends RowData>(
    column: DataTableColumn<TData>,
    server: ServerColumnConfig,
    facet: ServerFacetOption[] | ServerRangeFacet | undefined,
): DataTableColumn<TData> {
    const userMeta = column.meta as DataTableColumnMeta | undefined;

    return {
        ...column,
        meta: {
            ...serverMeta(server, facet, userMeta),
            ...userMeta,
            ...mergedOptions(facet, userMeta),
            ...mergedDisplay(server.display, userMeta?.display),
        } as DataTableColumnMeta,
        enableSorting: column.enableSorting ?? server.sortable,
        enableColumnFilter:
            column.enableColumnFilter ?? server.variant !== null,
        enableHiding: column.enableHiding ?? server.hideable,
    };
}

function serverMeta(
    server: ServerColumnConfig,
    facet: ServerFacetOption[] | ServerRangeFacet | undefined,
    userMeta: DataTableColumnMeta | undefined,
): DataTableColumnMeta {
    const base = {
        label: server.label,
        placeholder: server.placeholder ?? undefined,
    };
    const unit = server.unit ?? undefined;

    switch (server.variant) {
        case 'text':
        case 'boolean':
            return { ...base, variant: server.variant };
        case 'number':
            return { ...base, variant: 'number', unit };
        case 'range': {
            const range = isRangeFacet(facet) ? facet : undefined;

            return {
                ...base,
                variant: 'number',
                filter: 'range',
                unit,
                min: range?.min ?? undefined,
                max: range?.max ?? undefined,
            };
        }
        case 'date':
            return { ...base, variant: 'date' };
        case 'date-range':
            return { ...base, variant: 'date', filter: 'range' };
        case 'select':
        case 'multi-select':
            return {
                ...base,
                variant: server.variant,
                options: toOptions(facet, userMeta),
            };
        default:
            return base;
    }
}

/**
 * The page `display` wins; with the same type as the server one, only the keys
 * it declares (TanStack merges `meta` shallowly, so it is done here).
 */
function mergedDisplay(
    server: ColumnDisplay | null | undefined,
    page: ColumnDisplay | undefined,
): { display?: ColumnDisplay } {
    if (page === undefined) {
        return server ? { display: server } : {};
    }

    if (server?.type !== page.type) {
        return { display: page };
    }

    if (server.type === 'number' && page.type === 'number') {
        return {
            display: {
                ...server,
                ...page,
                format: { ...server.format, ...page.format },
            },
        };
    }

    return { display: { ...server, ...page } as ColumnDisplay };
}

/**
 * Options always carry the server count, even when the page redeclares them
 * (for example, to add icons).
 */
function mergedOptions(
    facet: ServerFacetOption[] | ServerRangeFacet | undefined,
    userMeta: DataTableColumnMeta | undefined,
): { options?: ColumnSelectOption[] } {
    return Array.isArray(facet) ? { options: toOptions(facet, userMeta) } : {};
}

function toOptions(
    facet: ServerFacetOption[] | ServerRangeFacet | undefined,
    userMeta: DataTableColumnMeta | undefined,
): ColumnSelectOption[] {
    if (!Array.isArray(facet)) {
        return [];
    }

    const declared =
        userMeta && 'options' in userMeta ? (userMeta.options ?? []) : [];

    return facet.map((option) => {
        const own = declared.find((item) => item.value === option.value);

        return {
            ...own,
            value: option.value,
            label: own?.label ?? option.label,
            count: option.count,
        };
    });
}

function isRangeFacet(
    facet: ServerFacetOption[] | ServerRangeFacet | undefined,
): facet is ServerRangeFacet {
    return facet !== undefined && !Array.isArray(facet);
}

function getColumnId<TData extends RowData>(
    column: DataTableColumn<TData>,
): string | undefined {
    if (column.id) {
        return column.id;
    }

    return 'accessorKey' in column && typeof column.accessorKey === 'string'
        ? column.accessorKey
        : undefined;
}

function getDefaultRowId<TData extends RowData>(
    row: TData,
    index: number,
): string {
    const id =
        typeof row === 'object' && row !== null && 'id' in row
            ? row.id
            : undefined;

    return typeof id === 'string' || typeof id === 'number'
        ? String(id)
        : String(index);
}

