    return (
        <FacetedItemSelectedContext.Provider value={isSelected}>
            <FacetedCommandItem
                data-slot="faceted-item"
                data-checked={isSelected || undefined}
                aria-checked={isSelected}
                onSelect={() => {
                    if (onSelect) {
                        onSelect(value);
                        return;
                    }
                    store.selectItem(value);
                }}
                {...props}
            />
        </FacetedItemSelectedContext.Provider>
    );
