interface DataTableFacetedFilterProps<TData extends RowData, TValue> {
    column?: Column<DataTableFeatures, TData, TValue>;
    title?: string;
    options: ColumnSelectOption[];
    multiple?: boolean;
}

export function DataTableFacetedFilter<TData extends RowData, TValue>({
    column,
    ...props
}: DataTableFacetedFilterProps<TData, TValue>) {
    if (!column) {
        return <DataTableFacetedFilterContent column={column} {...props} />;
    }

    return (
        <Subscribe
            source={column.table.atoms.columnFilters}
            selector={() => column.getFilterValue()}
        >
            {(filterValue) => (
                <DataTableFacetedFilterContent
                    column={column}
                    columnFilterValue={filterValue}
                    {...props}
                />
            )}
        </Subscribe>
    );
}

interface DataTableFacetedFilterContentProps<
    TData extends RowData,
    TValue,
> extends DataTableFacetedFilterProps<TData, TValue> {
    columnFilterValue?: unknown;
}

function DataTableFacetedFilterContent<TData extends RowData, TValue>({
    column,
    title = column?.columnDef.meta?.label ?? column?.id,
    options,
    multiple = false,
    columnFilterValue,
}: DataTableFacetedFilterContentProps<TData, TValue>) {
    const table = column?.table;
    const dir = useDirection();
    // Boolean filters store a single value ('true' / 'false').
    const isScalar = column?.columnDef.meta?.variant === 'boolean';
    const selectedValues = Array.isArray(columnFilterValue)
        ? columnFilterValue.filter(
              (value): value is string => typeof value === 'string',
          )
        : typeof columnFilterValue === 'string'
          ? [columnFilterValue]
          : [];
    const hasSelection = selectedValues.length > 0;

    function onValueChange(value: string | string[] | undefined) {
        const values = Array.isArray(value) ? value : value ? [value] : [];

        if (values.length === 0) {
            column?.setFilterValue(undefined);
        } else {
            column?.setFilterValue(isScalar ? values[0] : values);
        }
    }

    function onReset(event: React.MouseEvent) {
        event.stopPropagation();
        column?.setFilterValue(undefined);
    }

    return (
        <Faceted
            value={multiple ? selectedValues : selectedValues[0]}
            onValueChange={onValueChange}
            items={options}
            multiple={multiple}
        >
            <FacetedTrigger asChild>
                <Button variant="outline" className="border-dashed">
                    {hasSelection ? (
                        <span
                            aria-hidden="true"
                            className="rounded-sm opacity-70 transition-opacity hover:opacity-100"
                            onClick={onReset}
                        >
                            <CircleX />
                        </span>
                    ) : (
                        <CirclePlus />
                    )}
                    {title}
                    {hasSelection && (
                        <>
                            <Separator
                                orientation="vertical"
                                className="mx-0.5 data-[orientation=vertical]:h-4 data-[orientation=vertical]:self-center"
                            />
                            <FacetedValue>
                                {(selected) => (
                                    <FacetedBadgeList>
                                        {selected.length > 2 ? (
                                            <FacetedBadge>
                                                {getMessage(table, 'selected', {
                                                    count: selected.length,
                                                })}
                                            </FacetedBadge>
                                        ) : (
                                            selected.map((item) => (
                                                <FacetedBadge key={item.value}>
                                                    <span className="truncate">
                                                        {item.label}
                                                    </span>
                                                </FacetedBadge>
                                            ))
                                        )}
                                    </FacetedBadgeList>
                                )}
                            </FacetedValue>
                        </>
                    )}
                </Button>
            </FacetedTrigger>
            <FacetedContent
                aria-label={getMessage(table, 'filter', {
                    label: title ?? '',
                })}
                dir={dir}
                className="w-50"
            >
                <FacetedInput placeholder={title} />
                <FacetedList className="max-h-full">
                    <FacetedEmpty>
                        {getMessage(table, 'no_options')}
                    </FacetedEmpty>
                    <FacetedGroup className="max-h-75 scroll-py-1 overflow-x-hidden overflow-y-auto">
                        {options.map((option) => (
                            <FacetedItem
                                key={option.value}
                                value={option.value}
                            >
                                <FacetedItemCheckbox />
                                {option.icon && (
                                    <option.icon className="text-muted-foreground" />
                                )}
                                <span className="flex-1 truncate">
                                    {option.label}
                                </span>
                                {option.count !== undefined && (
                                    <FacetedItemCount>
                                        {formatNumber(
                                            option.count,
                                            {},
                                            table?.options.meta?.locale,
                                        )}
                                    </FacetedItemCount>
                                )}
                            </FacetedItem>
                        ))}
                    </FacetedGroup>
                    <FacetedClear>
                        {getMessage(table, 'clear_filters')}
                    </FacetedClear>
                </FacetedList>
            </FacetedContent>
        </Faceted>
    );
}

