import type { Column, RowData } from '@tanstack/react-table';

import { cn } from '@/lib/utils';
import * as React from 'react';

import type { DataTableFeatures } from '@/lib/data-table-features';
import { getMessage } from '@/lib/data-table-messages';
import type { ColumnFilterItem } from '@/lib/data-table-types';

import {
    getRangeFilterBounds,
    getValidRangeFilterBounds,
} from '@/lib/data-table-utils';
import { Input } from '@/components/ui/input';

const INVALID_RING_DELAY_MS = 500;

interface DataTableRangeFilterProps<
    TData extends RowData,
> extends React.ComponentProps<'div'> {
    filter: ColumnFilterItem;
    column: Column<DataTableFeatures, TData>;
    inputId: string;
    onFilterUpdate: (
        filterId: string,
        updates: Partial<Omit<ColumnFilterItem, 'filterId'>>,
    ) => void;
}

export function DataTableRangeFilter<TData extends RowData>({
    filter,
    column,
    inputId,
    onFilterUpdate,
    onBlur,
    className,
    ...props
}: DataTableRangeFilterProps<TData>) {
    const meta = column.columnDef.meta;
    const label = meta?.label ?? column.id;
    const bounds = meta?.variant === 'number' ? meta : undefined;

    const [startValue, endValue] = getRangeFilterValues(filter.value).map(
        getInputValue,
    );
    const [drafts, setDrafts] = React.useState<[string | null, string | null]>([
        null,
        null,
    ]);
    const [startInput, endInput] = getInputValues(drafts);
    const [showInvalid, setShowInvalid] = React.useState(false);
    const invalidTimeoutRef = React.useRef<number | undefined>(undefined);

    React.useEffect(
        () => () => window.clearTimeout(invalidTimeoutRef.current),
        [],
    );

    function onInvalidChange(isInvalid: boolean) {
        window.clearTimeout(invalidTimeoutRef.current);
        if (!isInvalid) {
            setShowInvalid(false);
            return;
        }
        if (showInvalid) return;
        invalidTimeoutRef.current = window.setTimeout(
            () => setShowInvalid(true),
            INVALID_RING_DELAY_MS,
        );
    }

    function getInputValues(
        nextDrafts: [string | null, string | null],
    ): [string, string] {
        return [
            nextDrafts[0] ?? startValue ?? '',
            nextDrafts[1] ?? endValue ?? '',
        ];
    }

    function onBoundsUpdate([start, end]: [
        number | undefined,
        number | undefined,
    ]) {
        onFilterUpdate(filter.filterId, {
            value: [start?.toString() ?? '', end?.toString() ?? ''],
        });
    }

    function onDraftChange(index: 0 | 1, value: string) {
        const nextDrafts: [string | null, string | null] =
            index === 0 ? [value, drafts[1]] : [drafts[0], value];
        setDrafts(nextDrafts);

        const nextBounds = getValidRangeFilterBounds(
            getInputValues(nextDrafts),
        );
        if (nextBounds) onBoundsUpdate(nextBounds);
        onInvalidChange(!nextBounds);
    }

    function onDraftCommit() {
        if (drafts[0] === null && drafts[1] === null) return;

        onBoundsUpdate(getRangeFilterBounds([startInput, endInput]));
        setDrafts([null, null]);
        onInvalidChange(false);
    }

    function onContainerBlur(event: React.FocusEvent<HTMLDivElement>) {
        onBlur?.(event);
        if (event.currentTarget.contains(event.relatedTarget)) return;
        onDraftCommit();
    }

    function onInputKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
        if (event.key === 'Enter') onDraftCommit();
    }

    return (
        <div
            data-slot="data-table-range-filter"
            className={cn('flex w-full items-center gap-2', className)}
            {...props}
            onBlur={onContainerBlur}
        >
            <Input
                id={`${inputId}-min`}
                type="number"
                aria-label={getMessage(column.table, 'minimum', { label })}
                aria-invalid={(showInvalid && drafts[0] !== null) || undefined}
                data-slot="data-table-range-filter-min"
                inputMode="numeric"
                placeholder={
                    bounds?.min?.toString() ?? getMessage(column.table, 'min')
                }
                className="w-full min-w-24"
                value={startInput}
                onChange={(event) => onDraftChange(0, event.target.value)}
                onKeyDown={onInputKeyDown}
            />
            <span
                data-slot="data-table-range-filter-separator"
                className="shrink-0 text-sm text-muted-foreground"
            >
                {getMessage(column.table, 'to')}
            </span>
            <Input
                id={`${inputId}-max`}
                type="number"
                aria-label={getMessage(column.table, 'maximum', { label })}
                aria-invalid={(showInvalid && drafts[1] !== null) || undefined}
                data-slot="data-table-range-filter-max"
                inputMode="numeric"
                placeholder={
                    bounds?.max?.toString() ?? getMessage(column.table, 'max')
                }
                className="w-full min-w-24"
                value={endInput}
                onChange={(event) => onDraftChange(1, event.target.value)}
                onKeyDown={onInputKeyDown}
            />
        </div>
    );
}

function getRangeFilterValues(value: string | string[]): [string, string] {
    if (Array.isArray(value)) return [value[0] ?? '', value[1] ?? ''];
    return [value, ''];
}

function getInputValue(value: string) {
    return value === '' || Number.isNaN(Number(value)) ? '' : value;
}

